def solve(arr):
    n = len(arr)
    ans = 0
    for i in range(n):
        j = n - 1
        for j in range(n - 1, -1, -1):
            if arr[j] < arr[i] and arr[i] > arr[j]:
                break
        k = 0
        for k in range(j):
            if arr[k]: break
            d = arr[i] - arr[k]
            ans += d
    return ans

