def find_parens(s):
    stack = []
    max_length = 0
    start_index = 0
    end_index = 0

    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        else:
            if stack:
                start = stack.pop()
                if not stack or (i - start > max_length):
                    max_length = i - start
                    start_index = start
                    end_index = i + 1

    return start_index, end_index

def solve(height):
    if not height or len(height) < 3:
        return 0

    total_water = 0
    left, right = 0, len(height) - 1
    left_max, right_max = 0, 0

    while left < right:
        if height[left] < height[right]:  # lesser height will be considered as boundary
            if height[left] >= left_max:
                left_max = height[left]  # update the left max
            else:
                total_water += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]  # update the right max
            else:
                total_water += right_max - height[right]
            right -= 1

    return total_water

