def get_max_lfh(heights, idx):
    l = idx
    r = idx

    heights[idx] += 1
    watermark = heights[idx]

    while heights[l - 1] < heights[idx] and l > 0:
        l -= 1 
        heights[l] += 1
        if heights[l] > watermark:
            watermark = heights[l]

    while heights[r + 1] < heights[idx] and r + 1 < len(heights):
        r += 1
        heights[r] += 1
        if heights[r] > watermark:
            watermark = heights[r]

    return l, r, watermark if l != 0 and r != len(heights) - 1 else 0

def solve(n: int) -> int:
    m = [0] * (n + 1)
    m[0] = 1
    commits = 0

    for i in range(1, n + 1):
        if m[i - 1] == 0:
            commits += 1
            m[i] = m[i - 1] if m[i - 1] == 0 else 0
        else:
            m[i] = 1

    return commits

